SELECT id, flow_no, agent_id, user_id, related_agent_id, related_user_id, asset_code, asset_name,
       change_type, amount, balance_after, biz_type, biz_id, remark, create_time
FROM dms_member_asset_flow
WHERE agent_id = #{agentId}

    AND asset_code = #{assetCode}

ORDER BY create_time DESC, id DESC

SELECT id, flow_no, agent_id, user_id, related_agent_id, related_user_id, asset_code, asset_name,
       change_type, amount, balance_after, biz_type, biz_id, remark, create_time
FROM dms_member_asset_flow
WHERE user_id = #{userId}

    AND asset_code = #{assetCode}

ORDER BY create_time DESC, id DESC
